import java.util.*;

public class Main {
    int maxSubarraySumCircular(int[] nums) {
        int total = 0;
        int curMax = 0;
        int maxSum = Integer.MIN_VALUE;                                           // best NON-wrapping subarray sum (standard Kadane's)
        int curMin = 0;
        int minSum = Integer.MAX_VALUE;                                          // worst (most negative) subarray sum, used to find the best WRAPPING subarray
        for (int x : nums) {
            total += x;
            curMax = Math.max(curMax + x, x);
            maxSum = Math.max(maxSum, curMax);
            curMin = Math.min(curMin + x, x);
            minSum = Math.min(minSum, curMin);
        }
        if (maxSum < 0) return maxSum;                                            // all elements negative: excluding everything isn't allowed, so don't wrap
        return Math.max(maxSum, total - minSum);                                  // best of: no wrap, or wrap (total minus the worst excluded middle)
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxSubarraySumCircular(new int[]{5, -3, 5}));
    }
}

